class Library:
  def __init__(self):
    self.books = []
    self.lent = {}  # book_name -> borrower
  def display_books(self):
    for b in self.books:
      status = ' (lent to ' + self.lent.get(b, '') + ')' if b in self.lent else ''
      print(b + status)
  def lend_book(self, book_name, borrower):
    if book_name not in self.books:
      print('Book not in library')
      return
    if book_name in self.lent:
      print('Currently lent out')
      return
    self.lent[book_name] = borrower
  def return_book(self, book_name):
    if book_name in self.lent:
      del self.lent[book_name]

lib = Library()
lib.books = ['Python', 'Java']
lib.lend_book('Python', 'Alice')
lib.lend_book('Python', 'Bob')
lib.return_book('Python')
lib.display_books()

class Employee:
  def __init__(self, name):
    self.name = name
class SalariedEmployee(Employee):
  def __init__(self, name, salary):
    super().__init__(name)
    self.salary = salary
  def calculate_pay(self):
    return self.salary
class HourlyEmployee(Employee):
  def __init__(self, name, hourly_rate, hours_worked):
    super().__init__(name)
    self.hourly_rate = hourly_rate
    self.hours_worked = hours_worked
  def calculate_pay(self):
    return self.hourly_rate * self.hours_worked

s = SalariedEmployee('Alice', 5000)
h = HourlyEmployee('Bob', 20, 40)
print(s.calculate_pay(), h.calculate_pay())

class BankAccount:
  def __init__(self, account_holder):
    self.account_holder = account_holder
    self._balance = 0
    self.transaction_history = []
  def deposit(self, amount):
    self._balance += amount
    self.transaction_history.append('deposit ' + str(amount))
  def withdraw(self, amount):
    if amount > self._balance:
      return
    self._balance -= amount
    self.transaction_history.append('withdraw ' + str(amount))
  def get_balance(self):
    return self._balance

acc = BankAccount('Alice')
acc.deposit(100)
acc.withdraw(30)
print(acc.get_balance(), acc.transaction_history)

from abc import ABC, abstractmethod
import math
class Shape(ABC):
  @abstractmethod
  def area(self):
    pass
class Circle(Shape):
  def __init__(self, radius):
    self.radius = radius
  def area(self):
    return math.pi * self.radius ** 2
class Rectangle(Shape):
  def __init__(self, width, height):
    self.width = width
    self.height = height
  def area(self):
    return self.width * self.height

c = Circle(2)
r = Rectangle(3, 4)
print(c.area(), r.area())

class Item:
  def __init__(self, name, price):
    self.name = name
    self.price = price
class ShoppingCart:
  def __init__(self):
    self.items = []
  def add(self, item):
    self.items.append(item)
  def __len__(self):
    return len(self.items)
  def __str__(self):
    lines = [i.name + ' - ' + str(i.price) for i in self.items]
    total = sum(i.price for i in self.items)
    lines.append('Total: ' + str(total))
    return '\n'.join(lines)

c = ShoppingCart()
c.add(Item('Apple', 2))
c.add(Item('Bread', 3))
print(len(c))
print(c)

class Student:
  def __init__(self, name):
    self.name = name
    self._grades = {}
  def add_grade(self, subject, score):
    self._grades.setdefault(subject, []).append(score)
  def get_average(self, subject=None):
    if subject is not None:
      lst = self._grades.get(subject, [])
    else:
      lst = [s for subj in self._grades for s in self._grades[subj]]
    return sum(lst) / len(lst) if lst else 0
  def get_grades(self):
    return dict(self._grades)

s = Student('Ali')
s.add_grade('Math', 90)
s.add_grade('Math', 80)
s.add_grade('Eng', 85)
print(s.get_average('Math'), s.get_average(), s.get_grades())

from abc import ABC, abstractmethod
class Vehicle(ABC):
  @abstractmethod
  def start(self): pass
  @abstractmethod
  def stop(self): pass
class Car(Vehicle):
  def __init__(self, name):
    self.name = name
  def start(self):
    return self.name + ' car started'
  def stop(self):
    return self.name + ' car stopped'
class Bike(Vehicle):
  def __init__(self, name):
    self.name = name
  def start(self):
    return self.name + ' bike started'
  def stop(self):
    return self.name + ' bike stopped'

c = Car('Tesla')
b = Bike('Hero')
print(c.start(), c.stop())
print(b.start(), b.stop())

class Notifier:
  def __init__(self, label):
    self.label = label
  def send(self, message):
    print('[' + self.label + '] ' + message)

class EmailNotifier(Notifier):
  def __init__(self, email):
    super().__init__('Email')
    self.email = email
  def send(self, message):
    print('Email to ' + self.email + ': ' + message)

class SMSNotifier(Notifier):
  def __init__(self, phone):
    super().__init__('SMS')
    self.phone = phone
  def send(self, message):
    print('SMS to ' + self.phone + ': ' + message)

class PushNotifier(Notifier):
  def __init__(self, device_id):
    super().__init__('Push')
    self.device_id = device_id
  def send(self, message):
    print('Push to ' + self.device_id + ': ' + message)

notifiers = [
  EmailNotifier('alice@example.com'),
  SMSNotifier('+91-9999999'),
  PushNotifier('DEVICE-001')
]

for n in notifiers:
  n.send('System alert: Server is down!')

class Stack:
  def __init__(self):
    self._items = []
  def push(self, item):
    self._items.append(item)
  def pop(self):
    return self._items.pop() if self._items else None
  def peek(self):
    return self._items[-1] if self._items else None
  def is_empty(self):
    return len(self._items) == 0

s = Stack()
s.push(1)
s.push(2)
print(s.pop(), s.peek(), s.is_empty(), s.pop(), s.pop())

class Patient:
  _registry = []

  def __init__(self, name, age, ward):
    self.name = name
    self.age = age
    self.ward = ward

  @classmethod
  def admit(cls, name, age, ward):
    p = cls(name, age, ward)
    cls._registry.append(p)
    return p

  @classmethod
  def get_by_ward(cls, ward):
    return [p for p in cls._registry if p.ward == ward]

  @classmethod
  def total_count(cls):
    return len(cls._registry)

  @staticmethod
  def is_adult(age):
    return age >= 18

Patient.admit('Alice', 34, 'ICU')
Patient.admit('Bob', 16, 'General')
Patient.admit('Carol', 28, 'ICU')

print('Total patients:', Patient.total_count())
for p in Patient.get_by_ward('ICU'):
  print(p.name, '| Adult:', Patient.is_adult(p.age))

class Product:
  def __init__(self, name, price, stock):
    self.name = name
    self.price = price
    self.stock = stock

class Order:
  def __init__(self, order_id):
    self.order_id = order_id
    self._items = []

  def add_item(self, product, quantity):
    if quantity > product.stock:
      print('Not enough stock for ' + product.name)
      return
    self._items.append((product, quantity))

  def calculate_total(self):
    return sum(p.price * qty for p, qty in self._items)

  def get_summary(self):
    lines = ['Order #' + str(self.order_id)]
    for product, qty in self._items:
      line_total = round(product.price * qty, 2)
      lines.append('  ' + product.name + ' x' + str(qty) + ' = $' + str(line_total))
    lines.append('Total: $' + str(round(self.calculate_total(), 2)))
    return '\n'.join(lines)

laptop = Product('Laptop', 999.99, 5)
mouse = Product('Mouse', 29.99, 20)

order = Order('ORD-001')
order.add_item(laptop, 1)
order.add_item(mouse, 2)
order.add_item(mouse, 25)
print(order.get_summary())

class Person:
  def __init__(self, name, age):
    self.name = name
    self.age = age
  def get_info(self):
    return 'Name: ' + self.name + ', Age: ' + str(self.age)

class Student(Person):
  def __init__(self, name, age, student_id):
    super().__init__(name, age)
    self.student_id = student_id
    self._grades = {}
  def add_grade(self, course, grade):
    self._grades[course] = grade
  def get_info(self):
    return super().get_info() + ', ID: ' + self.student_id

class GradStudent(Student):
  def __init__(self, name, age, student_id, research_topic):
    super().__init__(name, age, student_id)
    self.research_topic = research_topic
    self._papers = []
  def publish_paper(self, title):
    self._papers.append(title)
  def get_info(self):
    return super().get_info() + ', Research: ' + self.research_topic

gs = GradStudent('Alice', 26, 'G101', 'Machine Learning')
gs.add_grade('Statistics', 'A')
gs.publish_paper('Deep Learning in NLP')
print(gs.get_info())
print(gs._grades)
print(gs._papers)
